method compare(game: seq<int>, guess: seq<int>) returns (result: seq<int>)
    requires |game| == |guess| // The lengths of game and guess must be equal.
    ensures |result| == |game| // The result array will have the same length as game and guess.
    ensures forall i :: 0 <= i < |result| ==> result[i] == abs(game[i] - guess[i]) // Each element is the absolute difference of the corresponding elements in game and guess.
{
    var n := |game|;
    result := new int[n];
    var i := 0;
    while i < n
        invariant 0 <= i <= n // i is within bounds
        invariant result[..i] == [abs(game[j] - guess[j]) | j := 0 .. i] // The result so far contains the correct absolute differences
    {
        result[i] := abs(game[i] - guess[i]);
        i := i + 1;
    }
}
